using namespace wivrn::nxastc_packet; using Clock=std::chrono::steady_clock;
constexpr uint32_t W=64,H=64; constexpr size_t N=W*H,RAW=N*16,PACK=N*17;
struct Row{int gap,frame,mode;size_t anchor,delta;bool admitted;double enc,dec;};
std::vector<uint8_t> read_frame(const std::string& p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error(p);std::vector<uint8_t>b((std::istreambuf_iterator<char>(f)),{});if(b.size()!=16+RAW||b[4]!=8||b[5]!=8||b[7]!=0||b[8]!=2||b[9]!=0||b[10]!=0||b[11]!=2||b[12]!=0)throw std::runtime_error("not 512x512 ASTC 8x8: "+p);b.erase(b.begin(),b.begin()+16);return b;}
void pack_fixed(const std::vector<uint8_t>&ref,const std::vector<uint8_t>&cur,std::vector<uint8_t>&out){std::fill_n(out.begin(),N,4);for(size_t i=0;i<RAW;++i)out[N+i]=cur[i]^ref[i];}
void pack_wide(const std::vector<uint8_t>&ref,const std::vector<uint8_t>&cur,std::vector<uint8_t>&out,int radius){const int side=radius*2+1;for(int y=0;y<int(H);++y)for(int x=0;x<int(W);++x){const size_t i=size_t(y)*W+x;const uint8_t*c=cur.data()+i*16;unsigned best=129;uint8_t selected=0;for(int dy=-radius;dy<=radius;++dy)for(int dx=-radius;dx<=radius;++dx){const int nx=std::clamp(x+dx,0,int(W)-1),ny=std::clamp(y+dy,0,int(H)-1);const uint8_t*p=ref.data()+(size_t(ny)*W+nx)*16;unsigned d=detail::block_distance(c,p);if(d<best){best=d;selected=uint8_t((dy+radius)*side+dx+radius);}}out[i]=selected;const int dy=int(selected/side)-radius,dx=int(selected%side)-radius;const int nx=std::clamp(x+dx,0,int(W)-1),ny=std::clamp(y+dy,0,int(H)-1);const uint8_t*p=ref.data()+(size_t(ny)*W+nx)*16;for(int b=0;b<16;++b)out[N+i*16+b]=c[b]^p[b];}}
bool inverse_wide(const std::vector<uint8_t>&ref,const std::vector<uint8_t>&packed,std::vector<uint8_t>&out,int radius){if(packed.size()!=PACK)return false;const int side=radius*2+1;for(int y=0;y<int(H);++y)for(int x=0;x<int(W);++x){const size_t i=size_t(y)*W+x;const unsigned s=packed[i];if(s>=unsigned(side*side))return false;const int dy=int(s/side)-radius,dx=int(s%side)-radius,nx=std::clamp(x+dx,0,int(W)-1),ny=std::clamp(y+dy,0,int(H)-1);const uint8_t*p=ref.data()+(size_t(ny)*W+nx)*16;for(int b=0;b<16;++b)out[i*16+b]=p[b]^packed[N+i*16+b];}return true;}
void decode_mode(int mode,const std::vector<uint8_t>&ref,const std::vector<uint8_t>&packed,std::vector<uint8_t>&out){if(mode==0||mode==1){if(!reconstruct_motion_blocks(W,H,ref,packed,out))throw std::runtime_error("3x3 decode");}else{const int radius=mode==2?2:4;if(!inverse_wide(ref,packed,out,radius))throw std::runtime_error("wide decode");}}
int main(int argc,char**argv){if(argc!=2)return 1;std::vector<std::vector<uint8_t>> frames;for(int i=0;i<36;++i){char p[4096];std::snprintf(p,sizeof(p),"%s/%02d.astc",argv[1],i);frames.push_back(read_frame(p));}ZSTD_CCtx*ctx=ZSTD_createCCtx();ZSTD_DCtx*dctx=ZSTD_createDCtx();if(!ctx||!dctx)throw std::runtime_error("zstd context");std::vector<uint8_t>packed(PACK),decoded(PACK),restored(RAW),z(ZSTD_compressBound(PACK)),anchor_z(ZSTD_compressBound(RAW));std::vector<Row> rows;
 for(int gap:{1,2,4,8})for(int i=gap;i<36;++i){auto&cur=frames[i];auto&ref=frames[i-gap];size_t a=ZSTD_compressCCtx(ctx,anchor_z.data(),anchor_z.size(),cur.data(),cur.size(),3);if(ZSTD_isError(a))throw std::runtime_error("anchor compress");for(int order=0;order<4;++order){const int mode=(order+(i+gap)%4)%4;auto t=Clock::now();if(mode==0){if(!encode_motion_blocks(W,H,ref,cur,packed))throw std::runtime_error("9 pack");}else if(mode==1)pack_fixed(ref,cur,packed);else pack_wide(ref,cur,packed,mode==2?2:4);size_t n=ZSTD_compressCCtx(ctx,z.data(),z.size(),packed.data(),packed.size(),3);auto e=Clock::now();if(ZSTD_isError(n))throw std::runtime_error("delta compress");auto dt=Clock::now();size_t d=ZSTD_decompressDCtx(dctx,decoded.data(),decoded.size(),z.data(),n);if(ZSTD_isError(d)||d!=PACK)throw std::runtime_error("delta decompress");decode_mode(mode,ref,decoded,restored);if(restored!=cur)throw std::runtime_error("pixel mismatch");auto de=Clock::now();rows.push_back({gap,i,mode,a,n,uint64_t(n)*100<=uint64_t(a)*85,std::chrono::duration<double,std::milli>(e-t).count(),std::chrono::duration<double,std::milli>(de-dt).count()});}}
 std::puts("gap,mode,pairs,admitted,total_anchor_bytes,total_delta_bytes,mean_saving_pct,encode_zstd_p50_ms,encode_zstd_p95_ms,decode_inverse_p50_ms,decode_inverse_p95_ms");for(int gap:{1,2,4,8})for(int mode=0;mode<4;++mode){std::vector<double>times,decode_times;size_t pairs=0,adm=0,anchors=0,deltas=0;for(auto&r:rows)if(r.gap==gap&&r.mode==mode){++pairs;adm+=r.admitted;anchors+=r.anchor;deltas+=r.delta;times.push_back(r.enc);decode_times.push_back(r.dec);}std::sort(times.begin(),times.end());std::sort(decode_times.begin(),decode_times.end());const double p50=times[times.size()/2],p95=times[(times.size()*95+99)/100-1],d50=decode_times[decode_times.size()/2],d95=decode_times[(decode_times.size()*95+99)/100-1],save=100.0*(double(anchors)-double(deltas))/double(anchors);const char*name=mode==0?"neighbors9":mode==1?"same4":mode==2?"radius2_25":"radius4_81";std::printf("%d,%s,%zu,%zu,%zu,%zu,%.3f,%.6f,%.6f,%.6f,%.6f\n",gap,name,pairs,adm,anchors,deltas,save,p50,p95,d50,d95);}ZSTD_freeCCtx(ctx);ZSTD_freeDCtx(dctx);}
